-- Athena saved query (Product_B2C_Intl)
-- ID: a7e5a231-ae2a-46a0-8580-17a55bbbc752
-- Name: RTC AC Sort Click and Order Share - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp AS ( SELECT sd.mri_session_id, UPPER(user_type) AS user_type, CASE WHEN cardinality(filter(sd.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V0%')) > 0 THEN 'V0' WHEN cardinality(filter(sd.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V1%')) > 0 THEN 'V1' WHEN cardinality(filter(sd.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V2%')) > 0 THEN 'V2' ELSE 'others' END AS android_variant, src_id, dest_id FROM user_interaction.search_details sd JOIN lis.bo_mappings bo ON bo.vendor_id = sd.operator_id AND bo.is_rtc = 'RTC' WHERE sd.__time >= TIMESTAMP '2026-06-30 00:00:00' AND sd.__time < TIMESTAMP '2026-07-13 00:00:00' AND sd.country = 'IND' AND group_id > 0 AND sd.os = 'Android' AND sd.channel = 'MOBILE_APP' ), tuple_clicks AS ( SELECT DISTINCT ux.mri_session_id, TRY_CAST(ux.tuple_position AS INTEGER) AS tuple_position, CAST(ux.operator_id AS VARCHAR) AS operator_id FROM user_interaction.ui_ux_events ux INNER JOIN srp b ON ux.mri_session_id = b.mri_session_id WHERE ux.__time >= TIMESTAMP '2026-06-30 00:00:00' AND ux.__time < TIMESTAMP '2026-07-13 00:00:00' AND ux.header_country = 'IND' AND UPPER(ux.event_src) IN ('ANDROID', 'IOS') AND ux.tuple_position IS NOT NULL AND ux.tuple_position <> '' AND TRY_CAST(ux.tuple_position AS INTEGER) IS NOT NULL AND NOT ( ux.event_group = 'srp_click_event' AND ux.event_name IN ('RTC Expand', 'RTC Show Buses') ) ) SELECT 'ANDROID' AS channel, s.android_variant, s.user_type, s.src_id, s.dest_id, COUNT(DISTINCT s.mri_session_id) AS entry_sessions, COUNT(DISTINCT CONCAT( tc.mri_session_id, '|', CAST(tc.tuple_position AS VARCHAR), '|', COALESCE(tc.operator_id, 'na') )) AS total_tuple_clicks, COUNT(DISTINCT CASE WHEN tc.tuple_position <= 10 THEN CONCAT( tc.mri_session_id, '|', CAST(tc.tuple_position AS VARCHAR), '|', COALESCE(tc.operator_id, 'na') ) END) AS top10_tuple_clicks, COUNT(DISTINCT CASE WHEN tc.tuple_position <= 20 THEN CONCAT( tc.mri_session_id, '|', CAST(tc.tuple_position AS VARCHAR), '|', COALESCE(tc.operator_id, 'na') ) END) AS top20_tuple_clicks, CAST(COUNT(DISTINCT CASE WHEN tc.tuple_position <= 10 THEN CONCAT( tc.mri_session_id, '|', CAST(tc.tuple_position AS VARCHAR), '|', COALESCE(tc.operator_id, 'na') ) END) AS DOUBLE) / NULLIF(COUNT(DISTINCT CONCAT( tc.mri_session_id, '|', CAST(tc.tuple_position AS VARCHAR), '|', COALESCE(tc.operator_id, 'na') )), 0) AS top10_click_share, CAST(COUNT(DISTINCT CASE WHEN tc.tuple_position <= 20 THEN CONCAT( tc.mri_session_id, '|', CAST(tc.tuple_position AS VARCHAR), '|', COALESCE(tc.operator_id, 'na') ) END) AS DOUBLE) / NULLIF(COUNT(DISTINCT CONCAT( tc.mri_session_id, '|', CAST(tc.tuple_position AS VARCHAR), '|', COALESCE(tc.operator_id, 'na') )), 0) AS top20_click_share FROM srp s LEFT JOIN tuple_clicks tc ON s.mri_session_id = tc.mri_session_id GROUP BY 1, 2, 3, 4, 5 ORDER BY 1, 2, 3 DESC, 6 DESC ;
